// seed: tests/seed.spec.ts (гость) · прод, только чтение (запись заблокирована), вход не выполняется.
import { test, expect } from '@playwright/test';
import { prepareGuest, loginPopup, waitPopupSettled, LISTING_URL, LOAD } from './contact-popup.helpers';

test.use({ serviceWorkers: 'block' });

const SIZES = [
  { width: 412, height: 839 },
  { width: 375, height: 667 },
];
const SOURCES = [
  { name: 'объявление', url: LISTING_URL, button: 'הצג מספר טלפון' },
  { name: 'выдача /search', url: '/search', button: 'הצגת טלפון' },
];

test.describe('Связь с владельцем — возврат после входа из попапа', () => {
  for (const size of SIZES) {
    for (const src of SOURCES) {
      test(`Попап входа целиком в экране ${size.width}×${size.height} (${src.name}) #083d10 @android @prod-safe`, async ({ page }) => {
        await prepareGuest(page);
        await page.setViewportSize(size);
        await page.goto(src.url);

        await page.getByRole('button', { name: src.button }).first().click({ timeout: LOAD.timeout });
        await waitPopupSettled(page);
        const popup = loginPopup(page);

        await expect(popup, 'попап целиком в экране').toBeInViewport({ ratio: 1 });
        const box = (await popup.boundingBox())!;
        expect(box.x, 'левый край ≥ 0').toBeGreaterThanOrEqual(0);
        expect(box.y, 'верхний край ≥ 0').toBeGreaterThanOrEqual(0);
        expect(box.x + box.width, 'правый край ≤ ширины экрана').toBeLessThanOrEqual(size.width);
        expect(box.y + box.height, 'нижний край ≤ высоты экрана').toBeLessThanOrEqual(size.height);
        for (const name of [/SMS/, /Google/, 'המשך בלי הרשמה', 'Close']) {
          await expect(popup.getByRole('button', { name }), `кнопка ${name} в экране`).toBeInViewport({ ratio: 1 });
        }
        const docWidth = await page.evaluate(() => document.documentElement.scrollWidth);
        expect(docWidth, 'нет горизонтальной прокрутки').toBeLessThanOrEqual(size.width);
      });
    }
  }
});
